public class Student{private int id;private String name,rollNo,department,email,phone;private double marks;public Student(){}public Student(String n,String r,String d,String e,String p,double m){name=n;rollNo=r;department=d;email=e;phone=p;marks=m;}public Student(int i,String n,String r,String d,String e,String p,double m){this(n,r,d,e,p,m);id=i;}public int getId(){return id;}public void setId(int x){id=x;}public String getName(){return name;}public String getRollNo(){return rollNo;}public String getDepartment(){return department;}public String getEmail(){return email;}public String getPhone(){return phone;}public double getMarks(){return marks;}public String toString(){return String.format("ID:%d | Name:%s | Roll:%s | Dept:%s | Email:%s | Phone:%s | Marks:%.2f",id,name,rollNo,department,email,phone,marks);}}
